"use strict";
const { Plugin, PluginSettingTab, Notice, setIcon } = require("obsidian");

class ActivationSettings extends PluginSettingTab {
  display() {
    const root = this.containerEl;
    root.empty(); root.classList.add("nc-seed-settings");
    const card = root.createDiv({ cls: "nc-seed-card" });
    card.createEl("h3", { text: "激活笔记浏览器" });
    card.createEl("p", { text: "输入密钥，验证成功后自动安装最新版。", cls: "nc-seed-description" });
    const purchase = card.createEl("p", { cls: "nc-seed-purchase" });
    purchase.createSpan({ text: "还没有激活密钥？" });
    purchase.createEl("a", { text: "前往购买", attr: { "href": "https://wzyp.cn/item/7u3rnq", "target": "_blank", "rel": "noopener noreferrer" } });
    const form = card.createEl("form", { cls: "nc-seed-form" });
    const input = form.createEl("textarea", { cls: "nc-seed-key", attr: { "aria-label": "密钥", "placeholder": "请粘贴激活密钥", "rows": "3", "autocomplete": "off", "autocapitalize": "none" } });
    input.spellcheck = false;
    const submit = form.createEl("button", { text: "激活并安装", cls: "mod-cta nc-seed-submit", attr: { "type": "submit" } });
    const result = form.createDiv({ cls: "nc-seed-result", attr: { "role": "status", "aria-live": "polite" } });
    const show = () => {
      input.disabled = submit.disabled = this.plugin.busy;
      submit.textContent = this.plugin.busy ? "正在安装…" : "激活并安装";
      result.textContent = this.plugin.status;
      result.classList.toggle("is-error", this.plugin.failed);
    };
    this.plugin.renderStatus = show; show();
    form.addEventListener("submit", async event => {
      event.preventDefault();
      if (this.plugin.busy) return;
      const value = input.value.trim();
      try {
        const installed = await this.plugin.activateAndInstall(value, () => {
          input.value = "";
          const mark = result.createSpan({ cls: "nc-seed-check" }); setIcon(mark, "check");
        });
        if (!this.plugin.unloaded) input.value = "";
        if (!installed.restartRequired) this.app.setting?.close?.();
      } catch { /* activateAndInstall presents a sanitized, actionable error. */ }
    });
  }
  hide() { this.plugin.renderStatus = null; }
}

class NavigatorCardsSeed extends Plugin {
  async onload() {
    this.settings = { updateRepository: NC_LICENSE_CONFIG.repository };
    this.workQueue = this.settingsSaveQueue = Promise.resolve();
    this.cardsUnloaded = this.unloaded = false;
    this.busy = this.failed = false; this.status = "";
    this.updater = new NC_UPDATER.GithubUpdater(this);
    this.addSettingTab(new ActivationSettings(this.app, this));
  }
  setStatus(message, failed = false) {
    this.status = message; this.failed = failed;
    this.renderStatus?.();
  }
  async activateAndInstall(value, activated = () => {}) {
    if (this.busy) throw new Error("正在激活和安装，请稍候。");
    this.busy = true; this.setStatus("正在验证密钥…");
    let payload;
    try {
      payload = await NC_LICENSE.decodeActivationKey(value, NC_LICENSE_CONFIG);
      if (this.unloaded) throw new Error("基础版已停用，请重新启用后再试。");
      this.setStatus("正在核实更新权限…");
      await this.updater.activate(NC_LICENSE_CONFIG.repository, payload.token);
      payload.token = ""; payload = null;
      if (this.unloaded) throw new Error("基础版已停用，请重新启用后再试。");
      this.setStatus("验证成功，正在获取最新版…"); activated();
      const candidate = await this.updater.check();
      if (candidate.blocked) throw new Error(candidate.blocked);
      if (!candidate.newer) throw new Error("暂无可安装的完整版，请稍后重试。");
      if (this.unloaded) throw new Error("基础版已停用，请重新启用后再试。");
      const installed = await this.updater.install(candidate, message => this.setStatus(message));
      const message = installed.restartRequired ? `已安装 ${installed.version}，请重启 Obsidian 使用完整版。` : `已激活并安装笔记浏览器 ${installed.version}`;
      this.setStatus(message); new Notice(message, 6000);
      return installed;
    } catch (error) {
      const message = error?.message || "激活或安装失败，请稍后重试。";
      this.setStatus(message, true);
      if (this.unloaded) new Notice(message, 8000);
      throw new Error(message);
    } finally {
      if (payload) payload.token = "";
      this.busy = false; this.renderStatus?.();
    }
  }
  onunload() { this.cardsUnloaded = this.unloaded = true; this.renderStatus = null; }
}

module.exports = NavigatorCardsSeed;
